from collections import Counter

def baseline_accuracy(labels):
    return round(Counter(labels).most_common(1)[0][1] / len(labels), 2)

def beats_baseline(labels, predictions):
    acc = sum(a == p for a, p in zip(labels, predictions)) / len(labels)
    return round(acc, 2) > baseline_accuracy(labels)
